-- Corrige a codificação UTF-8 do prompt de preenchimento de licenças.
USE `gmodelo_dbp`;
SET NAMES utf8mb4;

UPDATE `ia_prompts`
SET `prompt_pt` = CONVERT( USING utf8mb4),
    `versao` = `versao` + 1,
    `alterado_em` = NOW()
WHERE `codigo` = 'LI_LICENCA_DOCUMENTO';

INSERT INTO `registros_migracao`
  (`codigo_migracao`,`origem`,`destino`,`tipo`,`versao`,`status`,`quantidade_registros`,`iniciada_em`,`concluida_em`,`detalhes`)
VALUES
  ('CORRIGIR_ACENTUACAO_PROMPT_LICENCA_169','gmodelo_dbp.ia_prompts','gmodelo_dbp.ia_prompts.prompt_pt','CORRECAO','1.0.0','CONCLUIDA',1,NOW(),NOW(),JSON_OBJECT('prompt','LI_LICENCA_DOCUMENTO','codificacao','utf8mb4'))
ON DUPLICATE KEY UPDATE `status`=VALUES(`status`),`concluida_em`=VALUES(`concluida_em`),`detalhes`=VALUES(`detalhes`);
